    /**
     * s 以word 的len 为大小分组, 然后以滑动窗口(len= words.len), 判断当前窗口中是否含有所有的words. 如果有,添加下标.
     * [s.len%word.len ==0 ,s.len%word.len = word.len-1]
     *
     * @param s
     * @param words
     * @return
     */
    public List<Integer> findSubstring(String s, String[] words) {

        HashSet<Integer> set = new HashSet<>();

        build(s);

        HashMap<Long, Integer> map = new HashMap<>();

        int len = words[0].length();
        for (String word : words) {
            long res = 0;
            for (int i = 0; i < len; i++) {
                res = i == 0 ? word.charAt(i) : res * base + word.charAt(i);
            }
            map.compute(res, (k, v) -> v == null ? 1 : v + 1);
        }

        HashMap<Long, Integer> wMap = new HashMap<>(); // record slide window every word counts.
        int n = s.length();
        int m = words.length;
        int size = map.size();
        System.out.println("s.len : " + n + ", a nums" + map.get(hash(0, 0)));
        for (int i = 0; i < len; i++) {
            int l = i, r = l;
            int cnt = 0;
            // [0,len ] ,[1,1+len],[len-1, x] // slide_window , 往右划, 右侧停止, 左侧检测.
            while (r <= n - len) {
                // move r , get a window, and size is word.len
                while (r <= n - len && cnt < m) {
                    long rh = hash(r, r + len - 1);
                    if (!map.containsKey(rh)) {
                        r += len;
                        l = r;
                        wMap.clear();
                        cnt = 0;
                        continue;
                    }
                    wMap.compute(rh, (k, v) -> v == null ? 1 : v + 1);
                    cnt++;
                    r += len;
                }

                // check if wMap contains all entry of map.
                if (checkMap(map, wMap)) {
                    set.add(l);
                }
                // move l to next verified word
                if (l > n - len) break;
                long lh = hash(l, l + len - 1);
                Integer val = wMap.computeIfPresent(lh, (k, v) -> v - 1);
                l += len;
                cnt--;
            }
            wMap.clear();
        }

        return set.stream().toList();
    }

    private boolean checkMap(HashMap<Long, Integer> map, HashMap<Long, Integer> wMap) {
        for (Long l : map.keySet()) {
            if (!wMap.containsKey(l)) return false;
            if (map.get(l) - wMap.get(l) != 0) return false;
        }
        return true;
    }


    int base = 433;
    long[] p; // p[i] = base^i
    long[] h;  // h[i] s[0,i]  rolling-hash

    void build(String s) {
        int n = s.length();
        p = new long[n];
        h = new long[n];
        for (int i = 0; i < n; i++) {
            p[i] = i == 0 ? 1 : base * p[i - 1];
            h[i] = i == 0 ? s.charAt(i) : s.charAt(i) + h[i - 1] * base;
        }
    }

    // str [l,r]'s hash = h[r]- h[l-1]*p[r-l+1]
    long hash(int l, int r) {
        long res = h[r];
        if (l > 0) res -= h[l - 1] * p[r - l + 1];
        return res;
    }


